// Claude looks at the photo itself, so "engaged" never relies on a hashtag.
const S = $('Trev settings').first().json;
const p = $input.first().json;
const ask = `This is a new Instagram post from ${S.GROOM.name}. Caption: "${p.caption}".
Is this an engagement announcement? Look for a ring on a hand, a proposal, or the caption saying so.
Reply with JSON only: {"engaged": true or false, "ring": true or false, "why": "under 12 words"}`;
return [{ json: { body: { model: S.MODEL, max_tokens: 1500, messages: [{ role: 'user', content: [
  { type: 'image', source: { type: 'url', url: p.image } },
  { type: 'text', text: ask } ] }] } } }];

const textOf = (node) => {
  const t = ($(node).first().json.content || []).map(c => c.text || '').join('').trim();
  if (!t) throw new Error(node + ' returned no text. Raise max_tokens or check the model name.');
  return t;
};
const jsonOf = (node) => {
  const t = textOf(node);
  const m = t.match(/\{[\s\S]*\}/);
  if (!m) throw new Error(node + ' did not return JSON: ' + t.slice(0, 120));
  return JSON.parse(m[0]);
};

const v = jsonOf('Claude: is that a ring?');
return [{ json: { engaged: v.engaged === true, ring: v.ring === true, why: String(v.why || '') } }];

const S = $('Trev settings').first().json;
const photos = $input.first().json.photos;
const counts = {};
for (const ph of photos) for (const t of ph.tagged) if (t !== S.GROOM.instagram) counts[t] = (counts[t] || 0) + 1;
const people = Object.entries(counts).map(([handle, n]) => {
  const p = ({"jackohara": {"name": "Jack O'Hara"}, "tomkells": {"name": "Tom Kelleher"}, "sammo_": {"name": "Sam Mitchell"}, "benny.d": {"name": "Ben Davies"}, "lukeyp": {"name": "Luke Pearson"}, "ryno": {"name": "Ryan Novak"}, "joshwhite": {"name": "Josh White"}, "dancoop": {"name": "Dan Cooper"}, "olliegrant": {"name": "Ollie Grant"}, "chrisb": {"name": "Chris Baxter"}, "mickyt": {"name": "Mick Turner"}, "harrisonlee": {"name": "Harry Lee"}, "willy.h": {"name": "Will Hughes"}, "jamesfitz": {"name": "James Fitzgerald"}, "nickyr": {"name": "Nick Russo"}, "pete.w": {"name": "Pete Walsh"}, "georgia.m": {"name": "Georgia Moss"}, "coach_dave": {"name": "Dave Collins"}, "kyle.brennan": {"name": "Kyle Brennan"}})[handle] || { name: handle };
  return { handle, name: p.name, n, family: (p.name || '').endsWith(' ' + S.GROOM.surname),
           first: Math.min(...photos.filter(ph => ph.tagged.includes(handle)).map(ph => ph.year)) };
});
const family = people.filter(p => p.family);
const mates = people.filter(p => !p.family).sort((a, b) => b.n - a.n)
  .slice(0, Math.max(0, S.GUEST_LIST_SIZE - 1 - family.length));
const list = [...mates, ...family];
const wildcard = family.sort((a, b) => a.n - b.n)[0] || null;   // the one nobody's met
return [{ json: { photosScanned: photos.length, years: `${Math.min(...photos.map(p => p.year))}-${Math.max(...photos.map(p => p.year))}`,
  guests: list, size: list.length + 1, wildcard } }];

const S = $('Trev settings').first().json;
const g = $input.first().json;
const names = g.guests.filter(p => !g.wildcard || p.handle !== g.wildcard.handle).map(p => p.name.split(' ')[0]);
let msg = `💍 <b>${S.GROOM.name} just got engaged.</b>\n\n🔎 Scanned ${g.photosScanned} tagged photos (${g.years}).\n`
  + `🧾 Guest list: <b>${g.size} blokes</b>\n${S.GROOM.name}, ${names.join(', ')}`;
if (g.wildcard) msg += `\n\n+ <b>${g.wildcard.name}</b>. Cousin. Tagged once, ${g.wildcard.first}. Nobody's ever met him.`;
return [{ json: { msg } }];

// Real forecast for the villa (Open-Meteo, free, no key), so the plan fits the surf and the weather.
const S = $('Trev settings').first().json;
const w = $('Weather at the villa').first().json.daily || {};
const m = ($('Surf at the villa').first().json.daily) || {};
const days = (w.time || []).slice(0, 3).map((d, i) => ({ day: i + 1,
  maxC: Math.round((w.temperature_2m_max || [])[i]), rainPct: (w.precipitation_probability_max || [])[i],
  windKmh: Math.round((w.wind_speed_10m_max || [])[i]), waveM: (m.wave_height_max || [])[i] }));
const ask = `You're Trev, the AI planning ${S.GROOM.name}'s bucks: ${S.GUEST_LIST_SIZE} blokes, ${S.TRIP.where}, ${S.TRIP.dates}, staying at ${S.VILLA.name}.
The forecast for the three days: ${JSON.stringify(days)}.
Write the itinerary as exactly 3 lines, one per day, like "Day 1 · Surf 🏄 3ft and clean, then beers 🍻".
It MUST have a surf session, 18 holes of golf, and beers every day. Rain doesn't cancel anything, these blokes play in the wet.
Put the surf on the day with the biggest waves. Mention the real wave size once. Under 12 words a line. No other text.`;
return [{ json: { days, body: { model: S.MODEL, max_tokens: 1500, messages: [{ role: 'user', content: ask }] } } }];

