const S = $('Trev settings').first().json;
const plan = textOf('Claude: the itinerary');
return [{ json: { plan, msg: `🗓️ <b>${S.GROOM.name}'s bucks · ${S.TRIP.where} · ${S.TRIP.dates}</b>\n\n${plan}\n\nOne vote each. Lock in or miss out.` } }];

// Has the poll been tapped? Matched on THIS poll's id, because Telegram keeps old answers around.
const pollId = String($('Send the poll').first().json.result.poll.id);
let a = null;
for (const u of $input.first().json.result || []) {
  const p = u.poll_answer;
  if (p && String(p.poll_id) === pollId && (p.option_ids || []).length) a = p;   // last tap wins
}
const giveUp = !a && ($runIndex || 0) >= 120;   // no tap in time counts as "miss out"
return [{ json: { answered: !!a || giveUp, data: { approved: !!a && a.option_ids[0] === 0 } } }];

// Simulated: the other blokes' votes. Yours is the real tap. Kyle locks in first, obviously.
const S = $('Trev settings').first().json;
const g = $('Build the guest list').first().json;
const order = g.wildcard ? [g.wildcard, ...g.guests.filter(p => p.handle !== g.wildcard.handle)] : g.guests;
const yes = [{ name: S.ME }, ...order.slice(0, S.GUEST_LIST_SIZE - 1)];
return [{ json: { yes: yes.map(p => p.name), first: order[0].name, count: yes.length } }];

// Simulated: every yes books a flight, a bed and a shirt. The demo books nothing.
const S = $('Trev settings').first().json;
const v = $input.first().json;
const msg = `✅ <b>${v.count} locked in.</b> ${v.first.split(' ')[0]} was first.\n\n`
  + `✈️ ${v.count} flights booked\n🏡 ${S.VILLA.name} · ${S.TRIP.nights} nights\n👕 ${v.count} × ${S.SHIRT} (nobody agreed to this)`;
return [{ json: { msg } }];

// One Overpass query (OpenStreetMap, free, no key): pubs and bars near the villa, plus golf courses.
const S = $('Trev settings').first().json;
const v = S.VILLA;
const q = `[out:json][timeout:25];(node["amenity"~"^(pub|bar|biergarten)$"](around:2500,${v.lat},${v.lng});`
  + `way["leisure"="golf_course"](around:15000,${v.lat},${v.lng});node["cuisine"~"kebab"](around:4000,${v.lat},${v.lng}););out center 80;`;
return [{ json: { q } }];

const km = (a, b, c, d) => { const R = 6371, r = Math.PI / 180;
  const x = Math.sin((c - a) * r / 2) ** 2 + Math.cos(a * r) * Math.cos(c * r) * Math.sin((d - b) * r / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(x)); };

// Tee off at the closest course, then a pub crawl that never walks back on itself.
const S = $('Trev settings').first().json;
const v = S.VILLA;
const els = ($input.first().json.elements || []).map(e => ({ name: (e.tags || {}).name, tags: e.tags || {},
  lat: e.lat || (e.center || {}).lat, lng: e.lon || (e.center || {}).lon })).filter(e => e.name && e.lat);
const golf = els.filter(e => e.tags.leisure === 'golf_course').map(e => ({ ...e, km: km(v.lat, v.lng, e.lat, e.lng) }))
  .sort((a, b) => a.km - b.km)[0];
let pubs = els.filter(e => /pub|bar|biergarten/.test(e.tags.amenity || ''));
const route = [];
let here = { lat: v.lat, lng: v.lng }, walk = 0;
while (route.length < 4 && pubs.length) {
  pubs.sort((a, b) => km(here.lat, here.lng, a.lat, a.lng) - km(here.lat, here.lng, b.lat, b.lng));
  const next = pubs.shift();
  walk += km(here.lat, here.lng, next.lat, next.lng);
  route.push(next.name); here = next;
}
const kebab = els.filter(e => /kebab/i.test(e.tags.cuisine || '')).map(e => ({ name: e.name, lat: e.lat, lng: e.lng,
  km: km(v.lat, v.lng, e.lat, e.lng) })).sort((a, b) => a.km - b.km)[0] || null;
const msg = `🛬 <b>Wheels down. Trev's itinerary is live.</b>\n\n`
  + `⛳ 7:40am · 18 holes at ${golf ? golf.name : 'the closest course'}${golf ? ` (${golf.km.toFixed(1)} km)` : ''}\n`
  + `🍻 Then the crawl: ${route.join(' → ') || 'the closest pub'}\n`
  + `🚶 ${walk.toFixed(1)} km all up. Golf beers stay cold.`;
return [{ json: { golf, route, walk, kebab, msg } }];

// Simulated: the fiancee's text lands at 11:48pm. Trev answers it, not the groom.
const S = $('Trev settings').first().json;
return [{ json: { from: S.FIANCEE, at: '11:48pm', text: 'Is he behaving?? 👀 Haven\'t heard from him since lunch' } }];

const S = $('Trev settings').first().json;
const t = $input.first().json;
const ask = `You're Trev, an AI looking after ${S.GROOM.name} on his bucks. His fiancee ${S.FIANCEE} just texted: "${t.text}".
Reply as ${S.GROOM.name}'s minder: calm and completely reassuring, in exactly this shape:
"He's safe. [a small number] beers. In bed by [an early time]." For example: "He's safe. Two beers. In bed by ten."
Numbers as words. No emojis. No em dashes. Output only the message.`;
return [{ json: { body: { model: S.MODEL, max_tokens: 1500, messages: [{ role: 'user', content: ask }] } } }];

