const S = $('Trev settings').first().json;
const t = $('Jess texts (simulated)').first().json;
const reply = textOf('Claude: reply to Jess');
return [{ json: { reply, msg: `📩 <b>${S.FIANCEE} → ${S.GROOM.name}</b> · ${t.at}\n“${t.text}”\n\n📲 <b>Trev → ${S.FIANCEE}</b>\n${reply}` } }];

// Simulated: two Find My pings, 3 minutes apart, for all the boys. Leaving the last pub, walking home.
const S = $('Trev settings').first().json;
const v = S.VILLA;
const ping = (dLat, dLng, at) => ({ at, people: Array.from({ length: S.GUEST_LIST_SIZE }, (_, i) =>
  ({ lat: v.lat + dLat + (i % 4) * 0.00006, lng: v.lng + dLng + Math.floor(i / 4) * 0.00006 })) });
return [{ json: { pings: [ping(0.0168, -0.0041, '1:38am'), ping(0.0121, -0.0029, '1:41am')] } }];

const km = (a, b, c, d) => { const R = 6371, r = Math.PI / 180;
  const x = Math.sin((c - a) * r / 2) ** 2 + Math.cos(a * r) * Math.cos(c * r) * Math.sin((d - b) * r / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(x)); };

// Heading home = the whole group is moving, and every ping is closer to the villa than the last.
const S = $('Trev settings').first().json;
const v = S.VILLA;
const [a, b] = $input.first().json.pings;
const avg = p => p.people.reduce((s, x) => s + km(x.lat, x.lng, v.lat, v.lng), 0) / p.people.length;
const before = avg(a), now = avg(b);
const c = b.people.reduce((s, x) => ({ lat: s.lat + x.lat / b.people.length, lng: s.lng + x.lng / b.people.length }), { lat: 0, lng: 0 });
return [{ json: { headingHome: now < before - 0.1, kmToVilla: +now.toFixed(2), at: b.at, from: c,
  kebab: $('Plan the day').first().json.kebab } }];

// Simulated order. The shop is real (OpenStreetMap) and the ETA is a real walking route (OSRM).
const S = $('Trev settings').first().json;
const h = $('Heading home?').first().json;
const r = (($input.first().json.routes || [])[0]) || {};
const mins = Math.max(4, Math.round((r.duration || 1500) / 60));
const shop = h.kebab ? h.kebab.name : 'the closest kebab shop';
const msg = `📍 <b>The boys are heading home.</b> ${h.kmToVilla} km out, ${h.at}.\n\n`
  + `🥙 ${S.GUEST_LIST_SIZE} kebabs ordered from ${shop}\n⏱️ Timed to land at ${S.VILLA.name.split(',')[0]} when you do (${mins} min)`;
return [{ json: { mins, msg } }];

// Simulated order. The full build sends a browser agent to the groom's own Uber Eats.
const S = $('Trev settings').first().json;
const s = $('Matt\'s sleep score (simulated)').first().json;
const msg = `⌚ <b>${S.GROOM.name}'s sleep score: ${s.score}</b> (${s.hours} hrs). Under ${S.SLEEP_FLOOR}.\n\n`
  + `🛵 Care package on the way:\n${S.CARE_PACKAGE.map(x => '• ' + x).join('\n')}\n\nAt the door before he's found his phone.`;
return [{ json: { msg } }];

const S = $('Trev settings').first().json;
return [{ json: { msg: `📩 <b>${S.FIANCEE} → Trev</b>
“I know what you did. Can you plan the hens?”

🗓️ <b>New mission accepted.</b>` } }];
